class Solution {
public:
    std::vector<int> closestPrimes(int left, int right) {
        std::vector<bool> is_prime(right + 1, true);
        is_prime[0] = is_prime[1] = false;
        for (int i = 2; i * i <= right; ++i) {
            if (is_prime[i]) {
                for (int j = i * i; j <= right; j += i) is_prime[j] = false;
            }
        }
        std::vector<int> primes;
        for (int i = left; i <= right; ++i) {
            if (is_prime[i]) primes.push_back(i);
        }
        if (primes.size() < 2) return {-1, -1};
        int best_diff = 1e9;
        std::vector<int> ans = {-1, -1};
        for (size_t i = 0; i + 1 < primes.size(); ++i) {
            int d = primes[i + 1] - primes[i];
            if (d < best_diff) {
                best_diff = d;
                ans = {primes[i], primes[i + 1]};
                if (d <= 2) break;
            }
        }
        return ans;
    }
};

class Solution {
    public int[] closestPrimes(int left, int right) {
        boolean[] isPrime = new boolean[right + 1];
        java.util.Arrays.fill(isPrime, true);
        isPrime[0] = isPrime[1] = false;
        for (int i = 2; i * i <= right; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j <= right; j += i) isPrime[j] = false;
            }
        }
        java.util.List<Integer> primes = new java.util.ArrayList<>();
        for (int i = left; i <= right; i++) {
            if (isPrime[i]) primes.add(i);
        }
        if (primes.size() < 2) return new int[]{-1, -1};
        int bestDiff = Integer.MAX_VALUE;
        int[] ans = new int[]{-1, -1};
        for (int i = 0; i + 1 < primes.size(); i++) {
            int d = primes.get(i + 1) - primes.get(i);
            if (d < bestDiff) {
                bestDiff = d;
                ans[0] = primes.get(i);
                ans[1] = primes.get(i + 1);
                if (d <= 2) break;
            }
        }
        return ans;
    }
}

